func (this *Test_org_eclipse_swt_widgets_Tree) Test_setData() {
	this.tree.Dispose()
	this.disposedIntentionally = true
	var image *swt.Image = swt.NewImageDeviceWidthHeight(upcastswtDisplayToswtDevice(swt.DisplayGetCurrent()), 20, 20)
	{
		defer func() {
			image.Dispose()
		}()
		this.shell.SetSize(200, 200)
		this.shell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
		this.shell.Open()
		this.WaitUntilIdle()
		for i := int32(0); i < 200; i++ {
			var tree *swt.Tree = swt.NewTree(upcastswtShellToswtComposite(this.shell), swt.VIRTUAL)
			tree.AddListener(swt.SetData, &ListenerFunc{fn: func(e *swt.Event) {
				var item *swt.TreeItem = castswtWidgetToswtTreeItem(e.Item)
				item.SetTextIndexString(0, "A")
				item.SetImage(image)
			}})
			this.WaitUntilIdle()
			tree.SetItemCount(1)
			this.WaitUntilIdle()
			junit.AssertEquals("A", tree.GetItem(0).GetTextIndex(0))
			junit.AssertEquals(image, tree.GetItem(0).GetImage())
			tree.Dispose()
		}
	}
}

