func (this *Test_org_eclipse_swt_widgets_Tree) Test_setItemCount_indexOf() {
	this.TestTreeRegularAndVirtual(jrt.NewRunnable(func() {
		this.tree.SetItemCount(10)
		var item_0 *swt.TreeItem = this.tree.GetItem(0)
		var item_2 *swt.TreeItem = this.tree.GetItem(2)
		item_0.SetItemCount(10)
		item_0.SetExpanded(true)
		var item_0_4 *swt.TreeItem = item_0.GetItem(4)
		{
			if !this.shell.GetVisible() {
				this.shell.SetLayout(upcastswtFillLayoutToswtLayout(swt.NewFillLayout()))
				this.shell.Pack()
				this.shell.Open()
			} else {
				this.tree.Pack()
			}
			SwtTestUtilProcessEvents()
			this.tree.SetItemCount(5)
			this.tree.SetItemCount(10)
			SwtTestUtilProcessEvents()
			junit.AssertEquals(int32(2), int32(this.tree.IndexOfItem(item_2)))
		}
		{
			item_0.SetItemCount(5)
			item_0.IndexOf(item_0_4)
			item_0.SetItemCount(10)
			junit.AssertEquals(int32(4), int32(item_0.IndexOf(item_0_4)))
		}
	}))
}

